  @JavascriptInterface public String exportProfileBackup(String profile){synchronized(stateLock){try{return ProfileArchive.export(MainActivity.this,profile);}catch(Exception e){try{return new JSONObject().put("nativeError",e.getMessage()).toString();}catch(Exception ignored){return "{\"nativeError\":\"Profile export failed\"}";}}}}
  @JavascriptInterface public String prepareLocalAudio(String data,String title,String profile){synchronized(stateLock){try{return LocalAudioService.prepare(MainActivity.this,data,title,profile).toString();}catch(Exception e){return "{\"error\":"+JSONObject.quote(e.getMessage())+"}";}}}
  @JavascriptInterface public String localAudioStatus(String profile){synchronized(stateLock){try{ProfileFiles.requireActive(MainActivity.this,profile);return LocalAudioService.status(profile).toString();}catch(Exception e){return "{}";}}}
  @JavascriptInterface public String localAudioCommand(String raw){try{JSONObject p=new JSONObject(raw);String profile=p.getString("profile"),op=p.getString("operation");ProfileFiles.requireActive(MainActivity.this,profile);if(!java.util.Arrays.asList("load","play","pause","seek","loop","stop").contains(op))throw new Exception("Invalid playback action.");Intent i=new Intent(MainActivity.this,LocalAudioService.class).setAction(op).putExtra("profile",profile).putExtra("token",p.optString("token")).putExtra("title",p.optString("title")).putExtra("seek",Math.round(p.optDouble("seek")*1000)).putExtra("start",Math.round(p.optDouble("start")*1000)).putExtra("end",Math.round(p.optDouble("end")*1000)).putExtra("loop",p.optBoolean("loop"));if("stop".equals(op))LocalAudioService.stop(MainActivity.this);else if("load".equals(op))startForegroundService(i);else startService(i);return "{\"ok\":true}";}catch(Exception e){return "{\"ok\":false,\"error\":"+JSONObject.quote(e.getMessage())+"}";}}
  @JavascriptInterface public String getLocalVoices(){if(localSpeech==null){runOnUiThread(()->{if(localSpeech==null)localSpeech=new LocalSpeech(MainActivity.this,value->emit("native-speech",value));});return "{\"ready\":false,\"voices\":[]}";}return localSpeech.voices();}
  @JavascriptInterface public void speakLocal(String raw){if(raw==null||raw.length()>120000)return;runOnUiThread(()->{try{String profile=new JSONObject(raw).getString("profileId");ProfileFiles.requireActive(MainActivity.this,profile);if(localSpeech==null)throw new IllegalStateException("Open Read aloud and wait for local voices to load.");localSpeech.speak(raw);}catch(Exception e){try{emit("native-speech",new JSONObject().put("state","error").put("error",e.getMessage()).toString());}catch(Exception ignored){}}});}
  @JavascriptInterface public void openCalendarEvent(String raw,String profile){if(raw==null||raw.length()>16000)return;runOnUiThread(()->{try{ProfileFiles.requireActive(MainActivity.this,profile);JSONObject event=new JSONObject(raw);String title=event.getString("title"),note=event.getString("description"),zone=event.getString("timeZone");long start=event.getLong("start"),end=event.getLong("end");if(title.trim().isEmpty()||title.length()>240||note.length()>5000||start<-2208988800000L||end>253402300800000L||end<=start||end-start>86400000L)throw new IllegalArgumentException("Choose a valid calendar event.");java.time.ZoneId.of(zone);Intent intent=new Intent(Intent.ACTION_INSERT,android.provider.CalendarContract.Events.CONTENT_URI).putExtra(android.provider.CalendarContract.Events.TITLE,title).putExtra(android.provider.CalendarContract.Events.DESCRIPTION,note).putExtra(android.provider.CalendarContract.Events.EVENT_TIMEZONE,zone).putExtra(android.provider.CalendarContract.EXTRA_EVENT_BEGIN_TIME,start).putExtra(android.provider.CalendarContract.EXTRA_EVENT_END_TIME,end).putExtra(android.provider.CalendarContract.EXTRA_EVENT_ALL_DAY,event.getBoolean("allDay"));startActivity(intent);}catch(ActivityNotFoundException e){emit("native-device-error","No calendar app is available. Export an .ics file from Calendar instead.");}catch(Exception e){emit("native-device-error",e.getMessage());}});}
  @JavascriptInterface public void requestQuickNoteTile(){runOnUiThread(()->{try{if(Build.VERSION.SDK_INT>=33){android.app.StatusBarManager bar=getSystemService(android.app.StatusBarManager.class);if(bar==null)throw new IllegalStateException();bar.requestAddTileService(new android.content.ComponentName(MainActivity.this,QuickNoteTile.class),"LW quick note",android.graphics.drawable.Icon.createWithResource(MainActivity.this,R.drawable.notification_leaf),getMainExecutor(),result->emit("native-device-message",result==android.app.StatusBarManager.TILE_ADD_REQUEST_RESULT_TILE_ADDED||result==android.app.StatusBarManager.TILE_ADD_REQUEST_RESULT_TILE_ALREADY_ADDED?"Quick note tile is ready.":"You can add LW quick note while editing Quick Settings."));}else emit("native-device-message","Edit your phone's Quick Settings panel and add LW quick note.");}catch(Exception e){emit("native-device-error","Quick Settings could not open. Edit the phone panel and add LW quick note manually.");}});}
  @JavascriptInterface public boolean getWatchMirroring(){return NativeServices.prefs(MainActivity.this).getBoolean("watchMirror",true);}
  @JavascriptInterface public void configureWatchMirroring(boolean enabled,String profile){synchronized(stateLock){try{ProfileFiles.requireActive(MainActivity.this,profile);NativeServices.prefs(MainActivity.this).edit().putBoolean("watchMirror",enabled).apply();android.app.NotificationManager nm=getSystemService(android.app.NotificationManager.class);for(android.service.notification.StatusBarNotification row:nm.getActiveNotifications())if(row.getId()==901||row.getId()==902||row.getId()==912||row.getId()==913)nm.notify(row.getTag(),row.getId(),android.app.Notification.Builder.recoverBuilder(MainActivity.this,row.getNotification()).setLocalOnly(!enabled).setOnlyAlertOnce(true).build());emit("native-device-message",enabled?"LW notifications can appear on a paired watch when its companion settings allow them.":"LW reminders will stay on this phone.");}catch(Exception e){emit("native-device-error",e.getMessage());}}}
