  @JavascriptInterface public String setActiveProfile(String id){synchronized(stateLock){try{if(pendingExport!=null||pendingWebFile!=null||pendingAudioRequest!=null)throw new IllegalStateException("Finish the file or microphone request before switching profiles");if(!ProfileFiles.active(MainActivity.this).equals(id))PersonalReminders.beforeSwitch(MainActivity.this);runOnUiThread(()->{if(localSpeech!=null)localSpeech.stop();});LocalAudioService.stop(MainActivity.this);ProfileFiles.activate(MainActivity.this,id);FocusNotification.sync(MainActivity.this);runOnUiThread(()->{PersonalReminders.sync(MainActivity.this);NativeServices.scheduleReminder(MainActivity.this);NativeServices.scheduleBackups(MainActivity.this);LearningWidget.updateAll(MainActivity.this);});return "{\"ok\":true}";}catch(Exception e){try{return new JSONObject().put("ok",false).put("error",e.getMessage()).toString();}catch(Exception ignored){return "{\"ok\":false}";}}}}

