  @JavascriptInterface public void exportText(String value,String name,String type){if(value.length()>150_000_000)return;chooseExport(value.getBytes(StandardCharsets.UTF_8),name.replaceAll("[^A-Za-z0-9._-]","_"),type.equals("text/markdown")?"text/markdown":"text/plain");}
  @JavascriptInterface public void exportLocalFile(String data,String name){try{int comma=data.indexOf(',');if(!data.startsWith("data:")||comma<0||data.length()>40_000_000)return;String type=data.substring(5,data.indexOf(';'));if(!type.matches("image/(png|jpeg|webp|gif)|application/pdf|text/(plain|markdown)|audio/[A-Za-z0-9.+-]+"))return;chooseExport(Base64.decode(data.substring(comma+1),Base64.DEFAULT),name.replaceAll("[^A-Za-z0-9._-]","_"),type);}catch(Exception ignored){emit("native-import-error","The attachment could not be exported");}}
  @JavascriptInterface public void startFrameProbe(){frameDurations.clear();runOnUiThread(()->{if(frameListener!=null)getWindow().removeOnFrameMetricsAvailableListener(frameListener);frameListener=(window,metrics,dropped)->frameDurations.add(metrics.getMetric(FrameMetrics.TOTAL_DURATION));getWindow().addOnFrameMetricsAvailableListener(frameListener,new Handler(Looper.getMainLooper()));});}
  @JavascriptInterface public String finishFrameProbe(){runOnUiThread(()->{if(frameListener!=null){getWindow().removeOnFrameMetricsAvailableListener(frameListener);frameListener=null;}});try{List<Long> values; synchronized(frameDurations){values=new ArrayList<>(frameDurations);}Collections.sort(values);int slow60=0,slow120=0;for(long ns:values){if(ns>16_666_667L)slow60++;if(ns>8_333_333L)slow120++;}return new JSONObject().put("frames",values.size()).put("p90Ms",values.isEmpty()?0:values.get(Math.min(values.size()-1,(int)(values.size()*.9)))/1_000_000d).put("over16_67ms",slow60).put("over8_33ms",slow120).put("scope","Android window frame durations during this sample").toString();}catch(Exception e){return "{}";}}
  @JavascriptInterface public String getVersion(){try{return getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception error){return "";}}
  @JavascriptInterface public String getState(String profile){synchronized(stateLock){try{ProfileFiles.requireActive(MainActivity.this,profile);String value=readPrivate();if(!value.isEmpty())new JSONObject(value);return value;}catch(Exception error){return"{\"nativeError\":\"The saved workspace could not be read. Its private recovery copies have been preserved.\"}";}}}
  @JavascriptInterface public String saveState(String value,long expected,String profile){synchronized(stateLock){try{ProfileFiles.requireActive(MainActivity.this,profile);if(value.length()>25_000_000)throw new IllegalArgumentException("Workspace exceeds 25 MB. Export older records before adding more.");String previous=readPrivate();long revision=previous.isEmpty()?0:new JSONObject(previous).optLong("revision",0);if(revision!=expected)return"{\"ok\":false,\"conflict\":true}";JSONObject object=new JSONObject(value);if(object.optInt("version")!=2||!object.has("courses"))throw new IllegalArgumentException("Invalid workspace");object.put("revision",revision+1);object.put("updatedAt",Instant.now().toString());dailyRecovery(previous);writePrivate(object.toString());NativeServices.prefs(MainActivity.this).edit().putString("interfaceLanguage",object.optJSONObject("learning")==null?"en":object.getJSONObject("learning").optString("interfaceLanguage","en")).apply();PersonalReminders.sync(MainActivity.this,object);FocusNotification.sync(MainActivity.this,object);NativeServices.onWorkspaceSaved(MainActivity.this);return new JSONObject().put("ok",true).put("revision",revision+1).put("updatedAt",object.getString("updatedAt")).toString();}catch(Exception error){try{return new JSONObject().put("ok",false).put("error",error.getMessage()).toString();}catch(Exception ignored){return"{\"ok\":false}";}}}}
  @JavascriptInterface public void completionFeedback(boolean sound,boolean haptics,boolean big,float volume){if(sound&&sounds!=null&&volume>0){float level=Math.max(0,Math.min(1,volume*2));sounds.play(big?daySound:completeSound,level,level,1,0,1);}if(haptics){Vibrator vibrator=(Vibrator)getSystemService(VIBRATOR_SERVICE);if(vibrator!=null&&vibrator.hasVibrator()){long[] pattern=big?new long[]{0,18,35,18,35,35}:new long[]{0,12,25,12};vibrator.vibrate(VibrationEffect.createWaveform(pattern,-1));}}}
  @JavascriptInterface public void setPerformance(String preference){
   if(!preference.equals("high")&&!preference.equals("balanced"))preference="auto";final String chosen=preference;
   runOnUiThread(()->{if(chosen.equals(displayPreference))return;displayPreference=chosen;WindowManager.LayoutParams attributes=getWindow().getAttributes();attributes.preferredDisplayModeId=0;attributes.preferredRefreshRate=0;
    if(!chosen.equals("auto")){Display display=getWindowManager().getDefaultDisplay();Display.Mode active=display.getMode();float maximum=60;for(Display.Mode mode:display.getSupportedModes())if(mode.getPhysicalWidth()==active.getPhysicalWidth()&&mode.getPhysicalHeight()==active.getPhysicalHeight())maximum=Math.max(maximum,mode.getRefreshRate());attributes.preferredRefreshRate=chosen.equals("high")?Math.min(120,maximum):60;}
    getWindow().setAttributes(attributes);
   });
  }
