  @JavascriptInterface public void hapticPattern(String raw){try{if(raw.length()>120)return;org.json.JSONArray values=new org.json.JSONArray(raw);if(values.length()>7)return;long[] pattern=new long[values.length()+1];for(int i=0;i<values.length();i++){long value=values.getLong(i);if(value<0||value>80)return;pattern[i+1]=value;}Vibrator vibrator=(Vibrator)getSystemService(VIBRATOR_SERVICE);if(vibrator!=null&&vibrator.hasVibrator()&&values.length()>0)vibrator.vibrate(VibrationEffect.createWaveform(pattern,-1));}catch(Exception ignored){}}
