 @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(appLock!=null&&appLock.result(request,result))return;if(request==WEB_FILE){ValueCallback<Uri[]> callback=pendingWebFile;pendingWebFile=null;Uri photo=pendingCameraPhoto;pendingCameraPhoto=null;Uri selected=photo!=null?(result==RESULT_OK&&PageCaptureProvider.ready(this,photo)?photo:null):result==RESULT_OK&&intent!=null?intent.getData():null;if(photo!=null)revokeUriPermission(photo,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);if(callback!=null)callback.onReceiveValue(selected==null?null:new Uri[]{selected});if(photo!=null&&result==RESULT_OK&&selected==null)emit("native-device-error","The camera photo is empty or exceeds 25 MB. Choose a smaller photo.");return;}if(request==BACKUP_FOLDER){if(result==RESULT_OK&&intent!=null&&intent.getData()!=null)try{NativeServices.chooseFolderResult(this,intent.getData(),intent.getFlags());}catch(Exception e){emit("native-device-error",e.getMessage());}emitDeviceStatus();return;}if(request==EXPORT){byte[] content=pendingExport;pendingExport=null;if(result!=RESULT_OK||intent==null||intent.getData()==null||content==null){emit("native-backup","cancelled");return;}try(OutputStream output=getContentResolver().openOutputStream(intent.getData())){if(output==null)throw new IllegalStateException("No file selected");output.write(content);emit("native-backup","saved");}catch(Exception error){emit("native-backup","failed");}}else if(request==SOUND_IMPORT&&result==RESULT_OK&&intent!=null&&intent.getData()!=null){
  Uri uri=intent.getData();try(InputStream input=getContentResolver().openInputStream(uri)){
   String name="Completion sound";try(Cursor cursor=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0);}
   String type=getContentResolver().getType(uri);if(type==null)type="audio/mpeg";if(type.equals("audio/x-m4a"))type="audio/mp4";if(type.equals("audio/vnd.wave"))type="audio/wav";
   if(!type.matches("audio/(mpeg|mp3|wav|x-wav|ogg|mp4|aac|webm)"))throw new IllegalArgumentException("Choose MP3, WAV, OGG, or M4A audio.");if(input==null)throw new IllegalArgumentException("The audio file could not be opened.");
   String url="data:"+type+";base64,"+Base64.encodeToString(readBounded(input,500_000),Base64.NO_WRAP);emit("native-sound",new JSONObject().put("name",name).put("dataURL",url).toString());
  }catch(Exception error){emit("native-import-error",error.getMessage());}
 }else if(request==IMPORT&&result==RESULT_OK&&intent!=null&&intent.getData()!=null){try(InputStream input=getContentResolver().openInputStream(intent.getData())){if(input!=null)emit("native-import",new String(readBounded(input,150_000_000),StandardCharsets.UTF_8));}catch(Exception error){emit("native-import-error",error.getMessage());}}}
 private void emitDeviceStatus(){emit("native-device-status",NativeServices.status(this).toString());}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==MICROPHONE){PermissionRequest pending=pendingAudioRequest;pendingAudioRequest=null;if(pending!=null){if(results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED&&trustedAudioOrigin(pending))pending.grant(new String[]{PermissionRequest.RESOURCE_AUDIO_CAPTURE});else pending.deny();}return;}if(request==ForestLocation.PERMISSION){forestLocation.permissionResult();return;}if(request==NOTIFICATIONS){FocusNotification.sync(this);PersonalReminders.sync(this);emit("native-organizer-status",PersonalReminders.status(this).toString());NativeServices.scheduleReminder(this);if(pendingTestNotification){pendingTestNotification=false;NativeServices.notifyStudy(this,true);}emitDeviceStatus();}}
 @Override protected void onResume(){super.onResume();if(appLock!=null)appLock.resume();if(forestLocation!=null)forestLocation.resume();if(localSpeech!=null)localSpeech.refreshVoices();if(web!=null){FocusNotification.sync(this);NativeServices.scheduleReminder(this);emitDeviceStatus();emit("native-foreground","");NativeServices.IO.execute(()->{PersonalReminders.sync(this);emit("native-organizer-status",PersonalReminders.status(this).toString());});}}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);readLaunchIntent(intent);if(!launchRoute.isEmpty())try{emit("native-open-target",new JSONObject().put("route",launchRoute).put("quickNote",launchQuickNote).put("quickReminder",launchQuickReminder).toString());}catch(Exception ignored){}else emit("native-open-course",launchCourse);}
 @Override public void onBackPressed(){if(appLock!=null&&appLock.locked()){moveTaskToBack(true);return;}web.evaluateJavascript("window.dispatchEvent(new Event('native-back'));",null);}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);web.saveState(out);}
 @Override protected void onPause(){if(appLock!=null)appLock.background();if(localSpeech!=null)localSpeech.stop();if(forestLocation!=null)forestLocation.background();if(frameListener!=null){getWindow().removeOnFrameMetricsAvailableListener(frameListener);frameListener=null;}web.evaluateJavascript("window.dispatchEvent(new Event('native-background'));",null);super.onPause();}
 @Override protected void onDestroy(){if(appLock!=null){appLock.close();appLock=null;}if(pendingCameraPhoto!=null){revokeUriPermission(pendingCameraPhoto,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);pendingCameraPhoto=null;}if(pendingWebFile!=null){pendingWebFile.onReceiveValue(null);pendingWebFile=null;}if(localSpeech!=null){localSpeech.close();localSpeech=null;}if(pendingAudioRequest!=null){pendingAudioRequest.deny();pendingAudioRequest=null;}if(forestLocation!=null)forestLocation.destroy();if(sounds!=null)sounds.release();if(printPreviewWeb!=null){printPreviewWeb.destroy();printPreviewWeb=null;}if(web!=null){web.removeJavascriptInterface("AndroidApp");web.destroy();}super.onDestroy();}
